"""Create and execute the project's explanatory notebook in the current environment."""
from __future__ import annotations

import json
import os
import sys
from pathlib import Path

import nbformat as nbf
from nbclient import NotebookClient

ROOT = Path(__file__).resolve().parents[1]
cache = ROOT / ".cache" / "jupyter"
for variable, child in [("JUPYTER_CONFIG_DIR", "config"), ("JUPYTER_DATA_DIR", "data"), ("JUPYTER_RUNTIME_DIR", "runtime"), ("IPYTHONDIR", "ipython")]:
    location = cache / child
    location.mkdir(parents=True, exist_ok=True)
    os.environ[variable] = str(location)
kernel = cache / "data" / "kernels" / "nonlife"
kernel.mkdir(parents=True, exist_ok=True)
(kernel / "kernel.json").write_text(json.dumps({"argv": [sys.executable, "-m", "ipykernel_launcher", "-f", "{connection_file}"], "display_name": "Non-life Python", "language": "python"}))
os.environ["MPLCONFIGDIR"] = str(ROOT / ".cache" / "matplotlib")
nb = nbf.v4.new_notebook()
md, code = nbf.v4.new_markdown_cell, nbf.v4.new_code_cell
nb.cells = [
    md("# French Motor Insurance Pricing\n\nA reproducible actuarial walkthrough of the completed full-data study.\n\n**业务问题：** 如何根据车辆和驾驶人特征估计年化预期赔款？\n\nMethodology: [scikit-learn worked example](https://scikit-learn.org/stable/auto_examples/linear_model/plot_tweedie_regression_insurance_claims.html). Actual data source: a pinned historical snapshot from the CASdatasets authors; see the manifest. This is a methodological reproduction with train-only preprocessing."),
    code("from pathlib import Path\nimport json, subprocess, sys\nimport pandas as pd\nfrom IPython.display import Image, display\nROOT = Path.cwd()\nif not (ROOT / 'config.json').exists():\n    ROOT = ROOT.parent\nassert (ROOT / 'config.json').exists(), 'Open this notebook from the project or notebooks folder.'\nsys.path.insert(0, str(ROOT))\nREPORTS = ROOT / 'reports'\nprint('Project:', ROOT.name)"),
    md("## 1. Reproduce or inspect\n\nSet `RECOMPUTE = True` to download verified source data if needed and rerun all models and sensitivities. The default displays the results already generated by the CLI. Raw data and model binaries are Git-ignored."),
    code("RECOMPUTE = False\nif RECOMPUTE:\n    subprocess.run([sys.executable, '-m', 'nonlife.run', '--download-only'], cwd=ROOT, check=True)\n    subprocess.run([sys.executable, '-m', 'nonlife.run', '--sensitivity'], cwd=ROOT, check=True)\nassert (REPORTS / 'run_metadata.json').exists(), 'Set RECOMPUTE=True, or run the CLI first.'\nmetadata = json.loads((REPORTS / 'run_metadata.json').read_text())\nconfig = metadata['config']\npd.Series({'policies': metadata['cleaning_audit']['policy_count'], 'training': metadata['train_policies'], 'test': metadata['test_policies'], 'positive_loss_test': metadata['test_positive_loss_policies'], 'ID_overlap': metadata['split_overlap']})"),
    md(r"""## 2. Actuarial targets and weights

Let $e_i$ denote exposure, $n_i$ adjusted claim count, and $S_i$ adjusted aggregate loss.

$$f_i=n_i/e_i,\qquad s_i=S_i/n_i,\qquad \pi_i=S_i/e_i.$$

Poisson models frequency with exposure weights; Gamma models positive severity with claim-count weights. The product $\hat f_i\hat s_i$ estimates annual pure premium. Tweedie models $\pi_i$ directly with exposure weights. Expected policy loss is $e_i\hat\pi_i$.

**注意：** 原基准对累计赔款、exposure 和 claim count 做了调整；这里的目标不是未经修改的原始损失。"""),
    code("pd.Series(metadata['cleaning_audit'], name='Cleaning audit')"),
    md("## 3. Holdout and preprocessing\n\nThe split is 75/25 with seed 0. Quantile bins, category levels and density scaling are fitted on training data only. Fixed benchmark regularization settings are used, with no test-set tuning. Separate policy IDs do not guarantee separate underlying insured entities.\n\nImplementation: `nonlife/models.py`; complete equations and limitations: `docs/METHODOLOGY.md`."),
    code("pd.Series(config, name='Fixed configuration')"),
    md("## 4. Test-set performance\n\nCompare deviance at an identical Tweedie power and target definition. Predicted / actual close to one indicates aggregate calibration. Gini describes ordering, not accurate monetary amounts."),
    code("metrics = pd.read_csv(REPORTS / 'metrics.csv')\nmetrics.loc[metrics['split'].eq('test'), ['model', 'predicted_actual', 'deviance_p1.5', 'deviance_p1.9', 'gini', 'weighted_mae']].round(4)"),
    code("display(Image(filename=str(REPORTS / 'figures' / 'overview.png'), width=1000))"),
    md("## 5. Segment calibration\n\nA model can match total loss while missing specific segments. These charts use exposure-weighted rates in each age band. Treat small groups cautiously; these are descriptive diagnostics without credibility adjustment or significance tests."),
    code("display(Image(filename=str(REPORTS / 'figures' / 'segment_calibration.png'), width=1000))\npd.read_csv(REPORTS / 'calibration_driver_age.csv').round(2)"),
    md("## 6. Tail sensitivity\n\nEach scenario refits on the same training IDs and evaluates against its own target. Compare models **within** a scenario. Different caps change the loss distribution, so absolute deviance across caps is not directly comparable."),
    code("sensitivity = pd.read_csv(REPORTS / 'sensitivity.csv')\nsensitivity[['loss_cap', 'model', 'actual_loss', 'predicted_actual', 'deviance_p1.9', 'gini']].round(4)"),
    md("## 7. What this demonstrates\n\n- Correct exposure and claim-count weighting, with a traceable data audit.\n- Separation of ranking performance and monetary calibration.\n- Explicit loss-cap assumptions and same-split sensitivity.\n- A reproducible codebase and offline interactive report.\n\n**Limitations:** single random holdout, potentially repeated risks, sparse large losses, no forward-year validation, no expenses or inflation loading.\n\nOpen `reports/dashboard.html` in a browser to interact with the figures. Next work could study group-aware validation and uncertainty before adding more complex models."),
]
nb.metadata["kernelspec"] = {"display_name": "Python 3", "language": "python", "name": "python3"}
nb.metadata["language_info"] = {"name": "python", "version": sys.version.split()[0]}
destination = ROOT / "notebooks" / "01_pricing_walkthrough.ipynb"
destination.parent.mkdir(exist_ok=True)
NotebookClient(nb, timeout=180, kernel_name="nonlife", resources={"metadata": {"path": str(ROOT)}}).execute()
nbf.write(nb, destination)
print(f"Executed and saved {destination}")
